// Keep only messages that say INFO (typed text or the template's Quick Reply button).
const out = [];
for (const { json } of $input.all()) {
  const names = Object.fromEntries((json.contacts ?? []).map((c) => [c.wa_id, c.profile?.name]));
  for (const m of json.messages ?? []) {
    const text = String(m.text?.body ?? m.button?.text ?? m.interactive?.button_reply?.title ?? '').trim().toUpperCase();
    if (text !== 'INFO') continue;
    out.push({
      json: {
        workspace: 'viseshta-avenues',
        name: names[m.from] || 'WhatsApp Lead',
        phone: '+' + m.from,
        source: 'Cold Database',
        campaign: 'Bulk Outreach - Excel',
        reply_keyword: 'INFO',
      },
    });
  }
}
return out;
